// Write-through : on écrit dans le cache ET la base en même temps
async function sauvegarderUtilisateur(id, data) {
  await db.user.update({ where: { id }, data });
  await cache.set(`user:${id}`, data); // synchrone, avant de continuer
}

// Write-back (write-behind) : on écrit d'abord dans le cache, la base suit plus tard
async function sauvegarderUtilisateurRapide(id, data) {
  await cache.set(`user:${id}`, data);
  queue.push({ type: 'sync-db', id, data }); // écriture différée, en arrière-plan
}

// Round-robin : chaque serveur reçoit les requêtes à tour de rôle
servers = [serverA, serverB, serverC];
function roundRobin() {
  const server = servers[current % servers.length];
  current++;
  return server;
}

// Least connections : la requête va au serveur le moins chargé actuellement
function leastConnections() {
  return servers.reduce((min, s) => (s.activeConnections < min.activeConnections ? s : min));
}

